<script setup lang="ts">
import { featureColors } from '../theme'
import { computed,onBeforeUnmount,ref,watch } from 'vue'
import { get } from '../api'
import type { Aliases,AliasCandidate,Entity,RoleLinks,PeriodProfiles } from '../api'
import { filters,exportJson,selection,useViewReadiness } from '../store'
const props=defineProps<{revision:number;entities:Entity[];resetKey:number}>()
const emit=defineEmits<{evidence:[id:string];entity:[id:string]}>()
const alias=ref('Boss'),candidateFilter=ref(''),data=ref<Aliases>(),chosenName=ref(''),error=ref(''),busy=ref(false)
const entityType=ref('Person'),roles=ref<RoleLinks>()
const periods=ref<PeriodProfiles>()
const periodsOpen=ref(false)
const manualOpen=ref(false)
const allCandidates=ref(false),includeDiagnostics=ref(false),splitDate=ref(''),splitDraft=ref(''),periodError=ref(''),loadedScope=ref('')
const queryScope=computed(()=>JSON.stringify({...filters.value,...weights.value,alias:alias.value,candidates:candidateFilter.value,diagnostics:includeDiagnostics.value,split_date:splitDate.value}))
const exportReady=computed(()=>!!data.value&&!busy.value&&!error.value&&loadedScope.value===queryScope.value)
const periodMax=computed(()=>Math.max(1,...(periods.value?.segments.flatMap(row=>row.hour_counts)||[])))
const weights=ref({neighbors:.30,temporal:.20,text:.30,context:.20,conflict:.20})
useViewReadiness('aliases',()=>exportReady.value)
const labels:Record<string,string>={neighbors:'邻居重合',temporal:'时间模式',text:'文本主题',context:'证据上下文',conflict:'互发反证惩罚'}
const colors:Record<string,string>=featureColors
const chosen=computed(()=>data.value?.items.find(c=>c.candidate===chosenName.value))
const summaryIds=computed(()=>{const evidence=chosen.value?.feature_evidence;const pair=evidence?.text[0]||evidence?.neighbors[0]||evidence?.context[0]||evidence?.temporal[0];return pair?[pair.alias_ids[0],pair.candidate_ids[0]].filter((id):id is string=>!!id):[]})
const visibleCandidates=computed(()=>{const rows=data.value?.items||[];return allCandidates.value?rows:rows.filter((row,index)=>index<3||row.candidate===chosenName.value)})
const people=computed(()=>props.entities.filter(n=>n.sub_type===entityType.value))
const note=ref(''),judgement=ref('uncertain'),storageError=ref('')
let request=0,timer:number|undefined
async function load(){const current=++request,scope=queryScope.value;busy.value=true;error.value='';data.value=undefined;roles.value=undefined;periods.value=undefined;try{const [result,links,profiles]=await Promise.all([get<Aliases>('aliases',{...filters.value,...weights.value,alias:alias.value,candidates:candidateFilter.value||undefined,diagnostics:includeDiagnostics.value}),get<RoleLinks>('aliases/roles',{...filters.value,entity_id:alias.value}),get<PeriodProfiles>('aliases/segments',{...filters.value,alias:alias.value,split_date:splitDate.value||undefined})]);if(current!==request)return;data.value=result;roles.value=links;periods.value=profiles;loadedScope.value=scope;if(!result.items.some(c=>c.candidate===chosenName.value))chosenName.value=result.items[0]?.candidate||''}catch(e){if(current===request)error.value=(e as Error).message}finally{if(current===request)busy.value=false}}
watch([()=>props.revision,alias,candidateFilter,splitDate,includeDiagnostics],()=>{if(splitDate.value&&(splitDate.value<=selection.start||splitDate.value>selection.end)){splitDate.value='';splitDraft.value=''}load()},{immediate:true})
watch(alias,()=>{selection.messageIds=[];allCandidates.value=false;includeDiagnostics.value=false})
watch(()=>props.resetKey,()=>{entityType.value='Person';alias.value='Boss';candidateFilter.value='';allCandidates.value=false;includeDiagnostics.value=false;splitDate.value='';splitDraft.value='';weights.value={neighbors:.30,temporal:.20,text:.30,context:.20,conflict:.20}})
watch(weights,()=>{window.clearTimeout(timer);timer=window.setTimeout(load,250)},{deep:true})
watch([alias,chosenName],()=>{try{const raw=localStorage.getItem(`mc3-note:${alias.value}:${chosenName.value}`);const saved=raw?JSON.parse(raw):{};note.value=saved.note||'';judgement.value=saved.judgement||'uncertain'}catch{storageError.value='浏览器无法读取本地分析标记。';note.value='';judgement.value='uncertain'}})
onBeforeUnmount(()=>window.clearTimeout(timer))
function choose(row:AliasCandidate){chosenName.value=row.candidate}
function changeType(){alias.value=entityType.value==='Vessel'?'Mako':'Boss';candidateFilter.value='';chosenName.value=''}
function inspectPeriod(ids:string[]){selection.messageIds=ids;if(ids[0])emit('evidence',ids[0])}
function save(){try{localStorage.setItem(`mc3-note:${alias.value}:${chosenName.value}`,JSON.stringify({note:note.value,judgement:judgement.value}));storageError.value='已保存在本浏览器；这是人工分析标记。'}catch{storageError.value='本地存储不可用，可导出分析记录。'}}
function applySplit(){if(splitDraft.value&&(splitDraft.value<=selection.start||splitDraft.value>selection.end)){periodError.value='分界必须晚于开始日期，且不晚于结束日期。';return}periodError.value='';splitDate.value=splitDraft.value}
function scenarioLabel(key:string){return key==='unique-content'?'只保留每种正文的首条记录':key.startsWith('without-day-')?'移除 '+key.slice(12):'移除'+(labels[key.slice(8)]||key)}
function exportComparison(){if(!exportReady.value)return;exportJson('mc3-alias-comparison.json',{alias:alias.value,alias_type:entityType.value,candidate:chosen.value,role_links:roles.value,period_profiles:periods.value,source_sha256:data.value?.source_sha256,diagnostics:data.value?.diagnostics,weights:weights.value,filters:filters.value,interpretation:'同类通信相似性不确认身份；人员与船舶角色不表示身份相等；船舶呼号可能由不同操作者使用',manual_analysis:{status:judgement.value,note:note.value}})}
</script>
<template><div class="alias-controls"><label>比较类型<select v-model="entityType" aria-label="比较类型" @change="changeType"><option value="Person">人物</option><option value="Vessel">船舶</option></select></label><label>比较起点<select v-model="alias" aria-label="疑似化名" data-testid="alias-select"><option v-for="p in people" :key="p.id" :value="p.id">{{p.id}}</option></select></label><select v-model="candidateFilter" aria-label="候选集合"><option value="">默认同类候选集</option><option v-for="p in people.filter(p=>p.id!==alias)" :key="p.id" :value="p.id">仅比较 {{p.id}}</option></select></div><details class="weights"><summary>特征权重与计算口径</summary><label v-for="(_,key) in weights" :key="key">{{labels[key]}}<input type="range" :aria-label="labels[key]+'权重'" min="0" max="1" step="0.05" v-model.number="weights[key]"><span>{{weights[key].toFixed(2)}}</span></label><p>按日期、小时与检索范围比较双方通信。前四项按权重和归一化，互发反证单独扣分，分值按原分 × 100 展示。画像包含发送与接收语境；文本移除实体名称后计算 TF-IDF，双方直接互发记录单独用于反证。</p></details><div v-if="error" class="error" role="alert">{{error}}</div><div v-if="busy&&!data" class="empty">正在比较通信特征…</div><div v-if="data?.items.length" class="alias-results"><section v-if="chosen" class="candidate-summary" data-testid="candidate-summary"><strong>{{alias}} ↔ {{chosen.candidate}}</strong><p>剔除互发后 {{chosen.sample_size.alias}} / {{chosen.sample_size.candidate}} 条；共同联系人 {{chosen.shared_neighbors.length}} 个；直接互发反证 {{chosen.refuting_ids.length}} 条。</p><div><span>双方示例：</span><button v-for="id in summaryIds" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button><button v-if="chosen.refuting_ids[0]" class="link" @click="emit('evidence',chosen.refuting_ids[0])">查看互发反证 ↗</button></div></section><div class="ranking scroll"><div class="ranking-head"><span>候选实体</span><span>邻居 / 时间 / 文本 / 上下文</span><span>相似分</span></div><button v-for="row in visibleCandidates" :key="row.candidate" class="candidate-row" :class="{chosen:row.candidate===chosenName}" @click="choose(row)" data-testid="alias-candidate"><span>{{row.candidate}}</span><span class="feature-cells"><i v-for="(color,key) in colors" :key="key" :title="`${labels[key]} · 特征 ${row.features[key]?.toFixed(3)} · 加权贡献 ${row.contributions[key]?.toFixed(3)}`" :style="{background:color+'22',color}">{{row.features[key]?.toFixed(2)}}</i></span><b>{{(row.score*100).toFixed(1)}}</b></button><button v-if="data.items.length>3" class="rank-toggle" @click="allCandidates=!allCandidates">{{allCandidates?'收起候选':`展开全部 ${data.items.length} 个候选`}}</button><div class="alias-legend"><span v-for="(color,key) in colors" :key="key"><i :style="{background:color}"></i>{{labels[key]}}</span></div></div><div class="candidate-detail" v-if="chosen" data-testid="alias-explanation"><div class="comparison-title">{{alias}} <span>↔</span> <button class="link" @click="emit('entity',chosen.candidate)">{{chosen.candidate}}</button></div><table class="feature-table"><thead><tr><th>特征</th><th>特征值</th><th>加权贡献</th></tr></thead><tbody><tr v-for="(value,key) in chosen.features" :key="key"><th>{{labels[key]}}</th><td>{{value.toFixed(3)}}</td><td>{{(chosen.contributions[key]||0).toFixed(3)}}</td></tr></tbody></table><div class="feature-evidence"><details v-for="(items,key) in chosen.feature_evidence" :key="key"><summary>{{labels[key]}} · {{items.length}} 组可查证据</summary><p v-if="!items.length">当前样本中未找到双方共同的此类证据。</p><article v-for="item in items" :key="item.label" :data-testid="key==='text'?'text-feature-evidence':'feature-evidence'"><strong>{{item.label}}</strong><small v-if="item.contribution!==undefined"> · 文本余弦贡献 {{item.contribution.toFixed(4)}}</small><small v-if="item.hour!==undefined"> · 双方 {{item.alias_count}} / {{item.candidate_count}} 条</small><div data-side="alias"><span>{{alias}}：</span><button v-for="id in item.alias_ids" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button></div><div data-side="candidate"><span>{{chosen.candidate}}：</span><button v-for="id in item.candidate_ids" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button></div><blockquote v-for="example in item.examples" :key="example.id"><button class="link mono" @click="emit('evidence',example.id)">{{example.id}}</button><p>…{{example.excerpt}}…</p></blockquote></article></details></div><p class="sample" v-if="chosen.shared_neighbors.length">共同邻居：{{chosen.shared_neighbors.join('、')}}</p><div v-for="text in chosen.conflicts" :key="text" class="counter-evidence">{{chosen.refuting_ids?.length||0}} 条直接互发通信支持将双方作为不同无线电身份考察。</div><div class="evidence-links"><span>支持/上下文样本</span><button v-for="id in chosen.support_ids" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button><span v-if="!chosen.support_ids.length">无直接支持样本，证据不足。</span></div><div v-if="chosen.refuting_ids?.length" class="evidence-links counter"><span>反证通信</span><button v-for="id in chosen.refuting_ids" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button></div><div v-if="chosen.context_ids.length" class="evidence-links"><span>共同事件/关系</span><button v-for="id in chosen.context_ids.slice(0,5)" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button></div><details class="manual-analysis" :open="manualOpen" @toggle="manualOpen=($event.target as HTMLDetailsElement).open"><summary>人工比较记录</summary><select v-model="judgement" aria-label="人工分析状态"><option value="uncertain">不确定 / 证据不足</option><option value="supporting">人工认为值得继续检查</option><option value="refuting">人工认为存在反证</option></select><textarea aria-label="人工分析备注" v-model="note" rows="2" placeholder="记录支持、反驳及待验证问题…"></textarea><button class="chip" @click="save">保存本地标记</button><span>{{storageError}}</span></details></div></div><div v-else-if="data&&!busy" class="empty">当前范围没有足够的两方通信可供比较。<br>请扩大时间范围，或更换比较起点与候选。</div><section v-if="data" class="sensitivity-review"><button class="chip" :disabled="busy||includeDiagnostics" @click="includeDiagnostics=true">检查权重与样本敏感性</button><template v-if="data.diagnostics"><p>默认首名 {{data.items[0]?.candidate||'证据不足'}}。固定词表与 IDF，逐一移除特征、同文重复或一个观察日，比较候选排名变化。</p><div class="sensitivity-table scroll"><table><thead><tr><th>扰动</th><th>首名</th><th>当前候选名次</th></tr></thead><tbody><tr v-for="row in data.diagnostics.scenarios" :key="row.key" data-testid="sensitivity-row"><td>{{scenarioLabel(row.key)}}<small>{{row.included_messages}} 条输入</small></td><td>{{row.ranking[0]?.candidate||'证据不足'}}</td><td>{{row.ranking.some(r=>r.candidate===chosenName)?row.ranking.findIndex(r=>r.candidate===chosenName)+1:'缺少样本'}}</td></tr></tbody></table></div></template></section><details v-if="periods" class="period-profiles" :open="periodsOpen" @toggle="periodsOpen=($event.target as HTMLDetailsElement).open"><summary>分时段对照 · {{periods.segments.length}} 个观察窗口</summary><div class="period-controls"><label>第二时段开始日期<input type="date" aria-label="第二时段开始日期" v-model="splitDraft" :min="selection.start" :max="selection.end"></label><button class="chip" @click="applySplit">应用分界</button><button class="chip" @click="splitDraft='';splitDate='';periodError=''">恢复等分</button></div><p v-if="periodError" role="alert">{{periodError}}</p><p>{{periods.split_date?`按 ${periods.split_date} 分界，第二段含当天`:'按当前观察日期等分为前后两段'}}。</p><div class="period-grid"><article v-for="row in periods.segments" :key="row.start" data-testid="period-profile"><strong>{{row.start.slice(5)}} — {{row.end.slice(5)}}</strong><p>{{row.count}} 条 · 发出 {{row.sent}} / 收到 {{row.received}} / 自环 {{row.self_loops}}</p><svg viewBox="0 0 288 70" aria-label="该时段的24小时通信分布"><g v-for="(count,hour) in row.hour_counts" :key="hour"><rect :x="hour*12" :y="50-count/periodMax*44" width="9" :height="count/periodMax*44" fill="#286a86"/><text v-if="hour%6===0" :x="hour*12" y="65" font-size="10" fill="#5c6c76">{{hour}}时</text><title>{{hour}}时：{{count}} 条</title></g></svg><div class="period-contacts"><button v-for="contact in row.contacts" :key="contact.entity_id" class="chip" @click="inspectPeriod(contact.message_ids)">{{contact.entity_id}} · {{contact.count}} <small>发{{contact.sent}}/收{{contact.received}}</small></button></div><button class="chip" data-testid="period-messages" :disabled="!row.count" @click="inspectPeriod(row.message_ids)">检查 {{row.count}} 条原文</button></article></div><p v-if="periods.contact_jaccard!==null">联系人重合 {{periods.contact_jaccard.toFixed(2)}} · 日内节奏相似 {{periods.hour_cosine?.toFixed(2)}}。</p><p v-else>缺少两段非空观察，暂不计算相似性。</p></details><details v-if="roles" class="role-links"><summary>比较起点的人员—船舶角色 · {{roles.items.length}} 条</summary><p>原图 Operates 关系连接人员与船舶；支撑通信按当前日期与检索条件筛选。</p><article v-for="row in roles.items" :key="row.relationship_id+row.person+row.vessel" data-testid="role-link"><strong>{{row.person}} ↔ {{row.vessel}}</strong><span>{{row.role||'角色未指定'}} · {{row.is_inferred?'文本推断':'原始记录'}}</span><button class="link mono" @click="emit('evidence',row.relationship_id)">{{row.relationship_id}}</button><div><button v-for="id in row.evidence_ids" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button><span v-if="!row.evidence_ids.length">无直接支撑通信</span></div></article><p v-if="!roles.items.length">当前范围没有可显示的角色证据。</p></details><button class="chip comparison-export" :disabled="!exportReady" @click="exportComparison">↓ 导出比较与人工标记</button></template>
<style scoped>
.feature-table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13px;color:var(--ink);font-variant-numeric:tabular-nums}.feature-table th,.feature-table td{text-align:right;padding:9px 12px;border-bottom:1px solid var(--selected)}.feature-table th:first-child{text-align:left}.feature-table th{font-weight:500}.feature-table thead{background:var(--surface)}

.candidate-summary{margin:0 14px 12px;padding:10px 12px;border-left:3px solid var(--blue);background:var(--surface);font-size:13px;line-height:1.6;color:var(--ink)}.candidate-summary p{margin:5px 0}.candidate-summary>div{display:flex;flex-wrap:wrap;gap:4px 8px}.candidate-summary .mono{font-size:12px}.rank-toggle{margin:7px 14px;font-size:12px}.feature-evidence{font-size:13px;color:var(--ink);line-height:1.7;margin-top:12px}.feature-evidence details{border-top:1px solid var(--selected);padding:8px 0}.feature-evidence summary{cursor:pointer}.feature-evidence article{padding:8px;background:var(--surface);margin:8px 0}.feature-evidence article>div{display:flex;flex-wrap:wrap;gap:5px}.feature-evidence .mono{font-size:12px}.feature-evidence blockquote{margin:8px 0;padding:4px 9px;border-left:2px solid var(--muted);background:white}.feature-evidence blockquote p{margin:4px 0;color:var(--ink)}.sensitivity-review{margin:12px 14px;font-size:13px;line-height:1.7;color:var(--ink)}.sensitivity-table{max-height:260px}.sensitivity-table table{width:100%;border-collapse:collapse}.sensitivity-table td,.sensitivity-table th{text-align:left;padding:6px;border-bottom:1px solid var(--selected);font-weight:400}.sensitivity-table small{display:block;color:var(--muted)}.period-controls{display:flex;align-items:end;gap:6px;flex-wrap:wrap;margin-top:10px}.period-controls label{display:flex;flex-direction:column;gap:5px}.period-controls input{font-size:12px;max-width:145px}

.alias-controls{display:flex;align-items:center;gap:8px;padding:12px 14px 0;flex-wrap:wrap}.alias-controls label{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}.alias-controls select{font-size:12px;padding:5px;max-width:170px}.alias-controls>.badge{margin-left:auto}.weights{padding:0 14px 12px;font-size:12px;color:var(--muted)}.weights summary{cursor:pointer}.weights summary span{float:right;font-size:12px;color:var(--muted)}.weights label{display:flex;align-items:center;justify-content:space-between;padding-top:10px;gap:12px}.weights input{width:50%;accent-color:var(--muted);padding:0}.weights p{font-size:12px;color:var(--muted);line-height:1.8}.ranking{max-height:290px;border-top:1px solid var(--selected);border-bottom:1px solid var(--selected)}.ranking-head,.candidate-row{display:grid;grid-template-columns:115px 1fr 52px;gap:10px;align-items:center;padding:9px 14px;font-size:12px}.ranking-head{color:var(--muted);font-size:12px;background:var(--panel)}.ranking-head>span:last-child{text-align:right;white-space:nowrap}.candidate-row{width:100%;border:0;border-radius:0;border-bottom:1px solid var(--surface);background:transparent;text-align:left;color:var(--muted);min-height:38px}.candidate-row.chosen{background:var(--surface);box-shadow:inset 3px 0 var(--muted)}.candidate-row b{text-align:right;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums}.feature-cells{display:grid;grid-template-columns:repeat(4,1fr);gap:4px}.feature-cells i{font-size:12px;padding:4px 2px;font-style:normal;text-align:center;border-radius:2px;font-variant-numeric:tabular-nums}.alias-legend{display:flex;gap:12px;padding:10px 14px;font-size:12px;color:var(--muted);flex-wrap:wrap}.alias-legend span{display:flex;gap:4px;align-items:center}.alias-legend i{width:7px;height:7px;display:inline-block;border-radius:50%}.candidate-detail{padding:16px 14px}.comparison-title{font-size:16px;color:var(--ink)}.comparison-title span{color:var(--muted);margin:0 8px}.comparison-title .link{font-size:16px}.sample{font-size:12px;line-height:1.8;color:var(--muted);margin:10px 0}.evidence-links{display:flex;gap:6px;flex-wrap:wrap;font-size:12px;margin:12px 0;max-height:95px;overflow:auto;color:var(--muted);line-height:1.8}.evidence-links .link{font-size:12px}.evidence-links>span:first-child{margin-right:4px;color:var(--muted)}.counter-evidence{font-size:12px;color:#9a783d;margin:10px 0;line-height:1.8;background:#fcf7eb;padding:8px}.counter .link{color:#a07b35}.manual-analysis{font-size:12px;color:var(--muted);margin:16px 0}.manual-analysis summary{cursor:pointer}.manual-analysis select{font-size:12px;margin:10px 0;max-width:100%}.manual-analysis textarea{display:block;width:100%;background:var(--panel);border:1px solid var(--border);border-radius:3px;color:var(--muted);padding:8px;font:inherit;margin-bottom:8px}.manual-analysis>span{font-size:12px;margin-left:8px;color:var(--muted)}.panel-note{font-size:12px}@media(max-width:700px){.ranking-head,.candidate-row{grid-template-columns:100px 1fr 48px}}
.role-links{margin:12px 14px;color:var(--muted);font-size:12px;line-height:1.8}.role-links summary{cursor:pointer}.role-links article{padding:10px 0;border-top:1px solid var(--selected);display:flex;flex-direction:column;gap:5px}.role-links article>div{display:flex;flex-wrap:wrap;gap:8px;max-height:100px;overflow:auto}.comparison-export{margin:8px 14px}
.period-profiles{margin:12px 14px;font-size:12px;color:var(--muted);line-height:1.8}.period-profiles summary{cursor:pointer}.period-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.period-grid article{min-width:0;background:var(--surface);padding:10px}.period-grid svg{width:100%}.period-contacts{display:flex;flex-wrap:wrap;gap:5px;max-height:140px;overflow:auto;margin:8px 0}.period-contacts small{font-size:12px}@media(max-width:1100px){.period-grid{grid-template-columns:1fr}}
</style>
